  const sw = w * LS;
  const sh = h * LS;
  const rotRad = rotDeg * Math.PI / 180;
  const ppx = cx + Math.sin(rotRad) * (sh / 2);
  const ppy = (cy + 2) - Math.cos(rotRad) * (sh / 2);

  const g = scene.add.graphics().setDepth(353 + depthOff);
  // 꼬리 몸통
  g.fillStyle(color, 0.93);
  g.fillPoints(tailPts(sw, sh), true);
  // 안쪽 광택
  g.fillStyle(0xffffff, 0.40);
  g.fillPoints(tailPts(sw * 0.38, sh * 0.88), true);
  // 끝 복슬한 털뭉치
  g.fillStyle(color, 0.65);
  g.fillEllipse(0, -(sh * 0.44), sw * 1.10, sw * 0.62);
  g.fillStyle(0xffffff, 0.58);
  g.fillEllipse(0, -(sh * 0.46), sw * 0.68, sw * 0.42);
  g.setPosition(ppx, ppy).setRotation(rotRad).setScale(0);

  scene.tweens.add({ targets: g, scale: 1, duration: 280, ease: 'Back.easeOut' });
  petalGfxs.push(g);
});

// 900ms 후 조용히 페이드아웃
const allObjs: Phaser.GameObjects.Graphics[] = [...petalGfxs, glow, base];

