  base.setPosition(cx, cy + 2);
  scene.tweens.add({ targets: base, scale: 1, duration: 220, ease: 'Back.easeOut' });

  // 여우 기운 글로우 — 흰/은빛
  const glow = scene.add.graphics().setDepth(353).setScale(0);
  glow.fillStyle(0xeef4ff, 0.18); glow.fillCircle(0, 0, 30 * LS);
  glow.fillStyle(0xfff0e8, 0.30); glow.fillCircle(0, 0, 16 * LS);
  glow.fillStyle(0xffffff, 0.50); glow.fillCircle(0, 0,  7 * LS);
  glow.setPosition(cx, cy - 10 * LS);
  scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });

  // 꼬리 형태: 뿌리 뾰족 → 몸통 빠르게 넓어짐 → 끝 둥글게
  const tailPts = (w: number, h: number): { x: number; y: number }[] => {
    const N = 24;
    const pts: { x: number; y: number }[] = [];
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const body  = Math.pow(t, 0.30);
      const taper = 1 - 0.18 * Math.pow(Math.max(0, (t - 0.80) / 0.20), 2);
      pts.push({ x:  (w / 2) * body * taper, y: h / 2 - t * h });
    }
    for (let i = N - 1; i >= 0; i--) {
      const t = i / N;
      const body  = Math.pow(t, 0.30);
      const taper = 1 - 0.18 * Math.pow(Math.max(0, (t - 0.80) / 0.20), 2);
      pts.push({ x: -(w / 2) * body * taper, y: h / 2 - t * h });
    }
    return pts;
  };

  // 꼬리: 바닥 한 점에서 뻗어나가는 형태
  const petalGfxs: Phaser.GameObjects.Graphics[] = [];
  LOTUS_DEFS.forEach(([rotDeg, w, h, color, depthOff]) => {
    const sw = w * LS;
    const sh = h * LS;
    const rotRad = rotDeg * Math.PI / 180;
    const ppx = cx + Math.sin(rotRad) * (sh / 2);
    const ppy = (cy + 2) - Math.cos(rotRad) * (sh / 2);

    const g = scene.add.graphics().setDepth(353 + depthOff);
    // 꼬리 몸통
    g.fillStyle(color, 0.93);
    g.fillPoints(tailPts(sw, sh), true);
    // 안쪽 광택
    g.fillStyle(0xffffff, 0.40);
    g.fillPoints(tailPts(sw * 0.38, sh * 0.88), true);
    // 끝 복슬한 털뭉치
    g.fillStyle(color, 0.65);
    g.fillEllipse(0, -(sh * 0.44), sw * 1.10, sw * 0.62);
    g.fillStyle(0xffffff, 0.58);
    g.fillEllipse(0, -(sh * 0.46), sw * 0.68, sw * 0.42);
    g.setPosition(ppx, ppy).setRotation(rotRad).setScale(0);

    scene.tweens.add({ targets: g, scale: 1, duration: 280, ease: 'Back.easeOut' });
    petalGfxs.push(g);
  });

  // 900ms 후 조용히 페이드아웃
  const allObjs: Phaser.GameObjects.Graphics[] = [...petalGfxs, glow, base];
  scene.time.delayedCall(900, () => {
    if (!scene.sys.isActive()) return;
    allObjs.forEach(obj => {
      scene.tweens.add({
        targets: obj, alpha: 0,
        duration: 500, ease: 'Quad.easeIn',
        onComplete: () => { if (obj.active) obj.destroy(); },
      });
    });
  });
}

