private _playRevivalLotus(px: number, py: number, scene: Phaser.Scene): void {
  ensureGlowDot(scene);
  const cx = px;
  const cy = py + 38;  // 플레이어 발 바닥

  // 위쪽(270°) 기준 ±64° 범위로 9개 꼬리 부채꼴 배치
  const angles = [-64, -48, -32, -16, 0, 16, 32, 48, 64]
    .map(d => (270 + d) * Math.PI / 180);
  const STEP = 7;  // 세그먼트 간격 (px)

  const allImgs: Phaser.GameObjects.Image[] = [];

  angles.forEach((angleRad, i) => {
    const color = REVIVAL_TAIL_COLORS[i] ?? 0xffffff;
    const alpha = color === 0xffffff ? 0.55 : 0.92;
    // 바깥쪽 꼬리일수록 뒤에 렌더링
    const depth = 355 - i * 0.2;

    REVIVAL_SEG_SCALES.forEach((scale, s) => {
      const dist = STEP * (s + 1);
      const img = scene.add.image(
        cx + Math.cos(angleRad) * dist,
        cy + Math.sin(angleRad) * dist,
        'glow_dot',
      )
        .setDepth(depth)
        .setBlendMode(Phaser.BlendModes.ADD)
        .setTint(color)
        .setScale(0)
        .setAlpha(alpha);

      scene.tweens.add({ targets: img, scale, duration: 280, ease: 'Back.easeOut' });
      allImgs.push(img);
    });
  });

  // 중앙 흰빛 글로우
  const hub = scene.add.image(cx, cy, 'glow_dot')
    .setDepth(360)
    .setBlendMode(Phaser.BlendModes.ADD)
    .setTint(0xffffff)
    .setScale(0);
  scene.tweens.add({ targets: hub, scale: 0.55, duration: 300, ease: 'Back.easeOut' });
  allImgs.push(hub);

  // 900ms 후 조용히 페이드아웃
  scene.time.delayedCall(900, () => {
    if (!scene.sys.isActive()) return;
    allImgs.forEach(img => {
      scene.tweens.add({
        targets: img, alpha: 0,
        duration: 500, ease: 'Quad.easeIn',
        onComplete: () => { if (img.active) img.destroy(); },
      });
    });
  });
}

